The <code>dis</code> module reveals the actual bytecode instructions the PVM executes.
Each <code>LOAD_FAST</code> pushes a local variable onto the evaluation stack;
<code>BINARY_OP</code> pops two operands, multiplies them, and pushes the result.

# Implicit None return
def no_return():
    x = 10   # does something but no return

result = no_return()
print(result)           # None
print(type(result))     # <class 'NoneType'>

# None as default / sentinel
def search(lst, target):
    for i, val in enumerate(lst):
        if val == target:
            return i
    return None   # explicit None when not found

idx = search([10, 20, 30], 20)
if idx is not None:
    print(f"Found at index {idx}")   # Found at index 1

# None as optional argument default
def greet(name, title=None):
    if title is None:
        return f"Hello, {name}!"
    return f"Hello, {title} {name}!"

print(greet("Alice"))             # Hello, Alice!
print(greet("Alice", "Dr."))      # Hello, Dr. Alice!
